/**
 * GENERATED — do not edit. Run `npm run bundle:worker`.
 *
 * `worker/`, reduced to the four constants `src/cloud/` needs to deploy it over
 * the Cloudflare REST API with no wrangler and no network fetch of the source.
 *
 * `WORKER_INPUTS_SHA256` is a digest of `worker/src/*.ts`, `worker/schema.sql`
 * and `worker/wrangler.toml`. `test/cloud/worker-bundle.test.ts` recomputes it
 * from disk and fails if the two disagree — which is what stops an edit to the
 * Worker from shipping a wizard that deploys the previous version of it. That
 * test also EXECUTES `WORKER_BUNDLE` against `worker/test/fake-d1.ts`, because
 * a matching hash only proves the input was current, not that the output runs.
 */

/** sha256 over worker/src/*.ts + schema.sql + wrangler.toml. */
export const WORKER_INPUTS_SHA256 = "f23aaf2cb332679c3b32b9200deb9da81b90b4995313e4be785d7472916d0eac";

/** `name` from worker/wrangler.toml — the Worker's name on Cloudflare. */
export const WORKER_NAME = "wwb-sync";

/**
 * `compatibility_date` from worker/wrangler.toml.
 *
 * Sent on every upload. The Workers API defaults an unset one to 2021-11-02,
 * which is a different runtime from the one the tests run against.
 */
export const WORKER_COMPATIBILITY_DATE = "2026-08-01";

/** The part name inside the multipart upload, and `main_module`. */
export const WORKER_MAIN_MODULE = "index.js";

/** worker/schema.sql — CREATE TABLE IF NOT EXISTS throughout, so re-applying is free. */
export const WORKER_SCHEMA_SQL = "-- The cloud half of docs/DATA_MODEL.md, verbatim.\n--\n--   wrangler d1 execute wwb --remote --file=worker/schema.sql\n--\n-- This file is also what worker/test/fake-d1.ts loads, so the tests run against\n-- the schema that is actually deployed rather than a hand-copied paraphrase of\n-- it. If the two ever drift, the tests are testing a fiction.\n\nCREATE TABLE IF NOT EXISTS work_interval (\n  seq             INTEGER PRIMARY KEY AUTOINCREMENT,  -- server-assigned; the ONLY pull watermark\n  id              TEXT    NOT NULL UNIQUE,            -- UUIDv7, minted CLIENT-SIDE at interval close\n  machine_id      TEXT    NOT NULL,                   -- IOPlatformUUID (ioreg, zero permissions)\n  started_at_ms   INTEGER NOT NULL,                   -- epoch ms UTC; the FIRST real signal\n  ended_at_ms     INTEGER NOT NULL,                   -- epoch ms UTC; the LAST REAL SIGNAL.\n                                                      -- Never the timeout instant. Never now().\n  duration_s      INTEGER NOT NULL,\n  end_reason      TEXT    NOT NULL,                   -- idle_timeout | sleep | lock | shutdown\n                                                      -- | app_quit | paused | crash_recovered | tap_lost\n  tz              TEXT    NOT NULL,                   -- IANA zone at close, e.g. 'America/Chicago'\n  local_date      TEXT    NOT NULL,                   -- 'YYYY-MM-DD' of started_at in tz, client-minted\n  key_events      INTEGER NOT NULL DEFAULT 0,\n  mouse_events    INTEGER NOT NULL DEFAULT 0,\n  camera_s        INTEGER NOT NULL DEFAULT 0,         -- seconds of this interval with a camera in use\n  jiggler_s       INTEGER NOT NULL DEFAULT 0,         -- seconds with OUR jiggler on — see PRD D1\n  app_version     TEXT    NOT NULL,\n  schema_v        INTEGER NOT NULL DEFAULT 1,\n  closed_local_ms INTEGER NOT NULL,                   -- client wall clock at close; skew diagnosis\n  server_ms       INTEGER NOT NULL                    -- Worker clock at insert\n);\nCREATE INDEX IF NOT EXISTS ix_wi_machine_start ON work_interval (machine_id, started_at_ms);\nCREATE INDEX IF NOT EXISTS ix_wi_local_date    ON work_interval (local_date);\n\nCREATE TABLE IF NOT EXISTS machine (\n  machine_id   TEXT PRIMARY KEY,\n  label        TEXT,\n  os_version   TEXT,\n  app_version  TEXT,\n  last_seen_ms INTEGER NOT NULL\n);\n\n-- ── The machine registry — docs/PRD.md §7 \"nothing is hardcoded to two\" ─────\n--\n-- One row per (machine, token). The token itself is NEVER here: only its\n-- SHA-256, as 64 lowercase hex characters. The plaintext exists in exactly two\n-- places — that Mac's Keychain, and the one screen that shows it if the\n-- Keychain refuses. Cloudflare holds a hash, so a dump of this database hands\n-- over nothing that can be presented as a credential.\n--\n-- NOTHING THE WORKER SERVES CAN WRITE THIS TABLE. Enrolment and revocation both\n-- go through the Cloudflare D1 REST API, which needs the Cloudflare API token —\n-- the credential that can already delete the whole database. A stolen bearer\n-- token can therefore append rows as itself and nothing more, exactly as before.\n--\n-- There is deliberately no `label` column. A machine's name has exactly one\n-- home, the `machine` table, written by that machine's own heartbeat; the\n-- wizard LEFT JOINs for it. A second copy of a name is a rename that can\n-- half-fail, and then a year of history disagrees with itself.\n--\n-- Rows are never deleted: revocation sets revoked_at_ms. Same rule as\n-- work_interval, for the same reason — who could write, and when, is history.\nCREATE TABLE IF NOT EXISTS machine_token (\n  token_sha256   TEXT    PRIMARY KEY,   -- lowercase hex SHA-256 of the bearer token\n  machine_id     TEXT    NOT NULL,      -- IOPlatformUUID; stamped onto every row this token writes\n  enrolled_at_ms INTEGER NOT NULL,\n  revoked_at_ms  INTEGER                -- NULL = live\n);\nCREATE INDEX IF NOT EXISTS ix_mt_machine ON machine_token (machine_id, revoked_at_ms);\n";

export const WORKER_BUNDLE = "// worker/src/auth.ts\nvar BEARER = /^Bearer[ \\t]+(.+)$/i;\nvar RegistryUnavailable = class extends Error {\n  constructor(cause) {\n    super(`the machine registry could not be read: ${String(cause)}`);\n    this.name = \"RegistryUnavailable\";\n  }\n};\nasync function sha256Hex(s) {\n  const digest = await crypto.subtle.digest(\n    \"SHA-256\",\n    new TextEncoder().encode(s)\n  );\n  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, \"0\")).join(\"\");\n}\nfunction timingSafeEqual(a, b) {\n  const subtle = crypto.subtle;\n  if (typeof subtle.timingSafeEqual === \"function\") {\n    if (a.byteLength !== b.byteLength) return false;\n    return subtle.timingSafeEqual(a, b);\n  }\n  if (a.byteLength !== b.byteLength) return false;\n  let diff = 0;\n  for (let i = 0; i < a.byteLength; i++) diff |= (a[i] ?? 0) ^ (b[i] ?? 0);\n  return diff === 0;\n}\nfunction presentedToken(req) {\n  const match = BEARER.exec(req.headers.get(\"authorization\") ?? \"\");\n  return match?.[1]?.trim() ?? \"\";\n}\nasync function authenticate(req, env) {\n  const presented = presentedToken(req);\n  if (presented === \"\") return null;\n  const hex = await sha256Hex(presented);\n  let row;\n  try {\n    row = await env.DB.prepare(\n      `SELECT token_sha256, machine_id FROM machine_token\n        WHERE token_sha256 = ? AND revoked_at_ms IS NULL`\n    ).bind(hex).first();\n  } catch (err) {\n    throw new RegistryUnavailable(err);\n  }\n  if (row === null) return null;\n  const enc = new TextEncoder();\n  if (!timingSafeEqual(enc.encode(hex), enc.encode(row.token_sha256))) {\n    return null;\n  }\n  return row.machine_id === \"\" ? null : row.machine_id;\n}\n\n// worker/src/fingerprint.ts\nasync function fingerprintSha256(ids) {\n  const canonical = [...ids].sort().join(\"\\n\");\n  const digest = await crypto.subtle.digest(\n    \"SHA-256\",\n    new TextEncoder().encode(canonical)\n  );\n  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, \"0\")).join(\"\");\n}\n\n// worker/src/routes.ts\nvar COLS = [\n  \"id\",\n  \"machine_id\",\n  \"started_at_ms\",\n  \"ended_at_ms\",\n  \"duration_s\",\n  \"end_reason\",\n  \"tz\",\n  \"local_date\",\n  \"key_events\",\n  \"mouse_events\",\n  \"camera_s\",\n  \"jiggler_s\",\n  \"app_version\",\n  \"schema_v\",\n  \"closed_local_ms\",\n  \"server_ms\"\n];\nvar COL_DEFAULTS = {\n  key_events: 0,\n  mouse_events: 0,\n  camera_s: 0,\n  jiggler_s: 0,\n  schema_v: 1\n};\nvar D1_MAX_BOUND_PARAMS = 100;\nvar ROWS_PER_STMT = Math.floor(D1_MAX_BOUND_PARAMS / COLS.length);\nvar IDS_PER_QUERY = D1_MAX_BOUND_PARAMS;\nvar MAX_ROWS_PER_REQUEST = 200;\nvar MAX_PULL_LIMIT = 1e3;\nasync function readJson(req) {\n  try {\n    return await req.json();\n  } catch {\n    return null;\n  }\n}\nfunction badRequest(why) {\n  return new Response(why, { status: 400 });\n}\nfunction intParam(url, name, fallback, min, max) {\n  const raw = url.searchParams.get(name);\n  if (raw === null || raw.trim() === \"\") return fallback;\n  const n = Number(raw);\n  if (!Number.isFinite(n)) return fallback;\n  return Math.min(Math.max(Math.trunc(n), min), max);\n}\nvar health = async () => Response.json({ ok: true, ms: Date.now() });\nvar postIntervals = async ({ req, env, machineId }) => {\n  const body = await readJson(req);\n  if (typeof body !== \"object\" || body === null) {\n    return badRequest(\"expected a JSON object\");\n  }\n  const { rows } = body;\n  if (!Array.isArray(rows)) return badRequest(\"expected rows[]\");\n  if (rows.length === 0) {\n    return Response.json({ present: [], server_ms: Date.now() });\n  }\n  if (rows.length > MAX_ROWS_PER_REQUEST) {\n    return new Response(\"too many rows\", { status: 413 });\n  }\n  const bad = rows.findIndex(\n    (r) => typeof r !== \"object\" || r === null || typeof r[\"id\"] !== \"string\" || r[\"id\"].length === 0\n  );\n  if (bad !== -1) return badRequest(`row ${bad} has no id`);\n  const wire = rows;\n  const serverMs = Date.now();\n  const stmts = [];\n  for (let i = 0; i < wire.length; i += ROWS_PER_STMT) {\n    const chunk = wire.slice(i, i + ROWS_PER_STMT);\n    const placeholders = chunk.map(() => `(${COLS.map(() => \"?\").join(\",\")})`).join(\",\");\n    const binds = chunk.flatMap(\n      (r) => COLS.map(\n        (c) => (\n          // ── The forgery guard. machine_id is stamped from the token and\n          //    server_ms from the Worker's clock; whatever the body claimed for\n          //    either is discarded here and never reaches the database.\n          c === \"machine_id\" ? machineId : c === \"server_ms\" ? serverMs : r[c] ?? COL_DEFAULTS[c] ?? null\n        )\n      )\n    );\n    stmts.push(\n      env.DB.prepare(\n        `INSERT INTO work_interval (${COLS.join(\",\")}) VALUES ${placeholders}\n         ON CONFLICT(id) DO NOTHING`\n      ).bind(...binds)\n    );\n  }\n  await env.DB.batch(stmts);\n  const ids = wire.map((r) => String(r[\"id\"]));\n  const present = [];\n  for (let i = 0; i < ids.length; i += IDS_PER_QUERY) {\n    const chunk = ids.slice(i, i + IDS_PER_QUERY);\n    const res = await env.DB.prepare(\n      `SELECT id, seq FROM work_interval WHERE id IN (${chunk.map(() => \"?\").join(\",\")})`\n    ).bind(...chunk).all();\n    present.push(...res.results);\n  }\n  return Response.json({ present, server_ms: serverMs });\n};\nvar getIntervals = async ({ env, url }) => {\n  const since = intParam(url, \"since\", 0, 0, Number.MAX_SAFE_INTEGER);\n  const limit = intParam(url, \"limit\", MAX_PULL_LIMIT, 1, MAX_PULL_LIMIT);\n  const r = await env.DB.prepare(\n    `SELECT * FROM work_interval WHERE seq > ? ORDER BY seq LIMIT ?`\n  ).bind(since, limit).all();\n  return Response.json({ rows: r.results });\n};\nvar heartbeat = async ({ req, env, machineId }) => {\n  const parsed = await readJson(req);\n  const b = typeof parsed === \"object\" && parsed !== null ? parsed : {};\n  const str = (v, fallback) => typeof v === \"string\" ? v : fallback;\n  await env.DB.prepare(\n    `INSERT INTO machine (machine_id,label,os_version,app_version,last_seen_ms)\n     VALUES (?,?,?,?,?)\n     ON CONFLICT(machine_id) DO UPDATE SET\n       label=excluded.label, os_version=excluded.os_version,\n       app_version=excluded.app_version,\n       -- commutative: an out-of-order heartbeat can never move it backwards\n       last_seen_ms=MAX(machine.last_seen_ms, excluded.last_seen_ms)`\n  ).bind(\n    machineId,\n    str(b.label, machineId),\n    str(b.osVersion, \"\"),\n    str(b.appVersion, \"\"),\n    Date.now()\n  ).run();\n  return Response.json({ ok: true });\n};\nvar getMachines = async ({ env }) => {\n  const r = await env.DB.prepare(\n    `SELECT machine_id, label, os_version, app_version, last_seen_ms\n       FROM machine ORDER BY machine_id`\n  ).all();\n  return Response.json({ machines: r.results });\n};\nvar fingerprint = async ({ env }) => {\n  const agg = await env.DB.prepare(\n    `SELECT COUNT(*) AS count, COALESCE(MAX(ended_at_ms),0) AS max_ended_at_ms\n     FROM work_interval`\n  ).first();\n  const idRows = await env.DB.prepare(\n    `SELECT id FROM work_interval ORDER BY id`\n  ).all();\n  const sha = await fingerprintSha256(idRows.results.map((r) => r.id));\n  return Response.json({\n    count: agg?.count ?? 0,\n    maxEndedAtMs: agg?.max_ended_at_ms ?? 0,\n    sha256: sha\n  });\n};\nvar ROUTES = {\n  \"GET /health\": { auth: false, handler: health },\n  \"POST /intervals\": { auth: true, handler: postIntervals },\n  \"GET /intervals\": { auth: true, handler: getIntervals },\n  \"POST /heartbeat\": { auth: true, handler: heartbeat },\n  \"GET /machines\": { auth: true, handler: getMachines },\n  \"GET /fingerprint\": { auth: true, handler: fingerprint }\n};\nfunction lookupRoute(method, pathname) {\n  const key = `${method} ${pathname}`;\n  return Object.hasOwn(ROUTES, key) ? ROUTES[key] : void 0;\n}\n\n// worker/src/index.ts\nvar UNAUTHORIZED = () => new Response(\"unauthorized\", {\n  status: 401,\n  headers: { \"www-authenticate\": \"Bearer\" }\n});\nvar NOT_FOUND = () => new Response(\"not found\", { status: 404 });\nvar index_default = {\n  async fetch(req, env) {\n    try {\n      const url = new URL(req.url);\n      const route = lookupRoute(req.method, url.pathname);\n      if (route && !route.auth) {\n        return await route.handler({ req, env, url, machineId: \"\" });\n      }\n      let machineId;\n      try {\n        machineId = await authenticate(req, env);\n      } catch (err) {\n        if (err instanceof RegistryUnavailable) {\n          console.error(\"wwb-sync registry unavailable\", err);\n          return new Response(\"machine registry unavailable\", { status: 503 });\n        }\n        throw err;\n      }\n      if (machineId === null) return UNAUTHORIZED();\n      if (!route) return NOT_FOUND();\n      return await route.handler({ req, env, url, machineId });\n    } catch (err) {\n      console.error(\"wwb-sync request failed\", err);\n      return new Response(\"internal error\", { status: 500 });\n    }\n  }\n};\nexport {\n  index_default as default\n};\n";
